'use strict';
const W=IUWorkspace,$=id=>document.getElementById(id);
let localWrites=0,connectionFrom=null,recoveryRaw=null;
let historyRange={from:'',to:''},chartMetric='following';let showArchived=false;let undoState=null;let offset=0;
let db=W.empty(),viewer='',lang='en',page='overview',query='',category='all',sort='username-asc',selected=new Set(),history=[],editing=null,simulation=null,rule=null,position=0,sessionId=null,toastTimer;
const t=(tr,en)=>lang==='tr'?tr:en;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?new Date(v).toLocaleString(lang==='tr'?'tr-TR':'en-GB'):'—';
const titles={overview:['◈ Genel bakış','◈ Overview'],accounts:['☷ Hesaplar','☷ Accounts'],review:['✓ İnceleme','✓ Review'],sessions:['▣ Oturumlar','▣ Sessions'],tasks:['◷ Görevler','◷ Tasks'],workflows:['⇢ İş akışları','⇢ Workflows'],snapshots:['▥ Taramalar','▥ Snapshots'],history:['↺ İşlem geçmişi','↺ Operation history'],health:['◇ Sistem sağlığı','◇ Health'],help:['? Yardım','? Help'],settings:['⚙ Ayarlar','⚙ Settings']};
const title=k=>titles[k][lang==='tr'?0:1],acc=()=>W.account(db,viewer),rows=()=>viewer?W.rows(acc()):[];
const matches=()=>W.filter(rows(),{query,category,sort,selected:[...selected],rule});
const btn=(action,label,data='',cls='')=>`<button type="button" data-action="${action}" data-id="${esc(data)}" class="${cls}">${esc(label)}</button>`;
const tag=v=>`<span class="tag">${esc(v)}</span>`;
function toast(v){$('toast').textContent=v;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4000)}
function fail(e){$('error').textContent=t('İşlem tamamlanamadı: ','Could not complete: ')+(e.message||String(e));$('error').hidden=false}
function download(name,value,type='application/json'){const url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);if(viewer&&acc().preferences.notifications)toast(t('Dışa aktarma dosyası hazır.','Export file is ready.'))}
function dialog(name,html,fn,label=t('Onayla','Confirm')){$('dialog-title').textContent=name;$('dialog-body').innerHTML=html;$('dialog-cancel').textContent=t('Vazgeç','Cancel');$('dialog-confirm').textContent=label;$('dialog-cancel').onclick=()=>$('dialog').close();$('dialog-confirm').onclick=async()=>{const b=$('dialog-confirm');b.disabled=true;try{if(await fn?.()!==false)$('dialog').close()}catch(e){fail(e)}finally{b.disabled=false}};$('dialog').showModal();$('dialog-cancel').focus()}
async function load(){const data=await chrome.storage.local.get([W.KEY,'iu_operation_history_v1']);try{db=W.parse(data[W.KEY])}catch{throw Error("INVALID_WORKSPACE_DATA")}try{history=JSON.parse(data.iu_operation_history_v1||'[]')}catch{history=[]}if(!Array.isArray(history))history=[];if(!db.accounts[viewer])viewer=Object.keys(db.accounts)[0]||'';if(viewer){lang=acc().preferences.language==='tr'?'tr':'en';sort=acc().preferences.defaultSort||'username-asc';category=acc().preferences.defaultFilter||'all';}await render()}
async function save(fn){const accountId=viewer,revision=db.revision;const previous=W.copy(acc());const next=W.copy(acc());await fn(next);let reply;localWrites++;try{reply=await chrome.runtime.sendMessage({type:'IU_WORKSPACE_COMMIT',expectedRevision:revision,accountId,account:next})}finally{localWrites--}if(!reply?.ok)throw Error(reply?.reason==='conflict'?t('Başka sekme veriyi değiştirdi; yenileyip tekrar dene.','Another tab changed data; reload and retry.'):t('Yerel kayıt yazılamadı.','Local save failed.'));if(viewer===accountId)undoState={accountId,account:previous};db.accounts[accountId]=next;db.revision=reply.revision;await render()}
function highlight(value){const str=String(value??''),q=query.trim().toLowerCase();if(!q)return esc(str);let folded='',offset=0,starts=[],ends=[];for(const char of str){const part=char.toLowerCase();for(let i=0;i<part.length;i++){starts.push(offset);ends.push(offset+char.length)}folded+=part;offset+=char.length}let result='',at=0,cursor=0,index;while((index=folded.indexOf(q,cursor))>=0){const start=starts[index],end=ends[index+q.length-1];if(start>=at){result+=esc(str.slice(at,start))+'<mark>'+esc(str.slice(start,end))+'</mark>';at=end}cursor=index+q.length}return result+esc(str.slice(at))}

function chartControls(){return `<div class="toolbar"><label>${t('Başlangıç (UTC)','From (UTC)')}<input type="date" id="range-from" value="${historyRange.from}"></label><label>${t('Bitiş (UTC)','Until (UTC)')}<input type="date" id="range-to" value="${historyRange.to}"></label><label>${t('Metrik','Metric')}<select id="chart-metric">${['following','followers','nonfollowers','mutual'].map(v=>`<option value="${v}" ${v===chartMetric?'selected':''}>${esc(({following:t('Takip edilen','Following'),followers:t('Takipçi','Followers'),nonfollowers:t('Geri takip etmeyen','Non-followers'),mutual:t('Karşılıklı','Mutual')})[v])}</option>`).join('')}</select></label>${btn('chart-range',t('Grafiği güncelle','Update chart'))}</div>`}
function table(items){return `<div class="table-wrap"><table><thead><tr><th>${t('Seç','Select')}</th><th>${t('Hesap','Account')}</th><th>${t('İlişki / etiket','Relationship / labels')}</th><th>${t('Yerel işlemler','Local actions')}</th></tr></thead><tbody>${items.slice(offset,offset+200).map(u=>`<tr><td><input type="checkbox" data-select="${u.id}" aria-label="${esc(u.username)}" ${selected.has(u.id)?'checked':''} ${u.protected?'disabled':''}></td><td><a href="https://www.instagram.com/${encodeURIComponent(u.username)}/" target="_blank" rel="noopener noreferrer">@${highlight(u.username)}</a><small class="sub">${highlight(u.full_name)}</small>${query.trim()&&u.notes.toLowerCase().includes(query.trim().toLowerCase())?`<small class="sub">${highlight(u.notes.slice(0,500))}</small>`:''}</td><td>${tag(u.relationship==='mutual'?t('Karşılıklı','Mutual'):u.relationship==='nonfollowers'?t('Geri takip etmeyen','Non-follower'):t('Bilinmiyor','Unknown'))}${u.protected?tag(t('Korumalı','Protected')):''}${u.favorite?tag('★'):''}${u.labels.map(v=>'<span class="tag">'+highlight(v)+'</span>').join('')}</td><td><div class="actions">${btn('protect',u.protected?'◇':'◆',u.id)}${btn('favorite',u.favorite?'★':'☆',u.id)}${btn('note',t('Not / etiket','Note / labels'),u.id)}</div></td></tr>`).join('')}</tbody></table></div><p class="muted">${items.length} ${t('eşleşme. Sayfa','matches. Page')} ${Math.floor(offset/200)+1} / ${Math.max(1,Math.ceil(items.length/200))} ${items.length>200?btn('table-prev',t('Önceki','Previous'))+btn('table-next',t('Sonraki','Next')):''}</p>`}
function chart(){const list=acc().snapshots.filter(s=>(!historyRange.from||s.at.slice(0,10)>=historyRange.from)&&(!historyRange.to||s.at.slice(0,10)<=historyRange.to));const values=list.map(s=>W.analytics(acc(),s)[chartMetric]),max=Math.max(1,...values.filter(v=>v!=null));let segments=[],current=[];values.forEach((v,i)=>{if(v==null){if(current.length)segments.push(current);current=[]}else current.push([30+i*540/Math.max(1,list.length-1),140-v/max*110,i])});if(current.length)segments.push(current);return `<svg class="chart" viewBox="0 0 600 160" role="img" aria-label="${esc(t('Saklanan tarama gözlemleri','Stored scan observations'))}">${segments.map(points=>`<polyline points="${points.map(p=>p.slice(0,2).join(',')).join(' ')}"/>${points.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="4"><title>${esc(date(list[p[2]].at)+' · '+values[p[2]])}</title></circle>`).join('')}`).join('')}</svg><small>${t('Eksik değerler çizilmez; yalnızca saklanan gözlemler gösterilir.','Unavailable values are omitted; only stored observations are shown.')}</small>`}
function overview(){const m=W.analytics(acc());return `<section class="workspace-hero"><p class="eyebrow">${t("SANA AİT ÇALIŞMA ALANI","YOUR OWN WORKSPACE")}</p><h2>${t("Daha az karmaşa.<br>Daha çok kontrol.","Less clutter.<br>More control.")}</h2><p>${t("Hesaplarını düzenle, önemli bağlantılarını koru.","Organize accounts and protect important connections.")}</p></section><div class="grid">${[[t('Takip edilen','Following'),m.following],[t('Takipçi','Followers'),m.followers],[t('Geri takip etmeyen','Non-followers'),m.nonfollowers],[t('Karşılıklı','Mutual'),m.mutual],[t('Korumalı','Protected'),rows().filter(u=>u.protected).length],[t('Seçili','Selected'),selected.size]].filter((_,i)=>!(acc().preferences.hiddenCards||[]).includes(i)).map(([name,value])=>`<div class="card"><small>${esc(name)}</small><strong>${value??'—'}</strong></div>`).join('')}</div><div class="split"><section class="section"><h2>${t('Yerel gözlem geçmişi','Local observation history')}</h2>${chartControls()}${chart()}<small>${t('Gerçek takip tarihi veya bağımsız profil toplamı değildir.','Not actual follow dates or independently verified profile totals.')}</small></section><section class="section"><h2>${t('Son tarama','Last scan')}</h2><p>${esc(date(acc().snapshots.at(-1)?.at))}</p><p>${t('Geri takip etmeyen oranı','Non-follower percentage')}: ${m.nonfollowerPercent==null?'—':m.nonfollowerPercent.toFixed(1)+'%'}</p><p>${t('Takip / takipçi oranı','Following / follower ratio')}: ${m.ratio==null?'—':m.ratio.toFixed(2)}</p></section></div><section class="section"><h2>${t('Yerel öneriler','Local recommendations')}</h2>${recommendationCards()}${acc().preferences.flags?.advanced?`<p>${rows().filter(u=>!u.notes).length} ${t('yerel kayıtta not yok. İstersen inceleme sırasına ekleyebilirsin. Bu bir ilişki veya risk çıkarımı değildir.','local records have no notes. Optionally add them to review; this is not a relationship or risk inference.')}</p>${btn('review-unnoted',t('Yerel inceleme listesi hazırla','Prepare local review list'))}`:''}<p>${m.followers===null?t('Takipçi verisi yok: ilişki analizi için karşılaştırmalı taramayı tamamla.','Follower data unavailable: complete a comparison scan.'):t('Kayıtlı ilişki verilerini Hesaplar ekranında inceleyebilirsin.','Review stored relationship data in Accounts.')}</p><p>${history.filter(e=>e.accountId===viewer&&e.category==='uncertain').length} ${t('belirsiz işlem: yeniden göndermeden önce Instagram üzerinde kontrol et.','uncertain operations: review on Instagram before another attempt.')}</p></section>`}
function accounts(){return `<div class="toolbar"><input id="search" type="search" value="${esc(query)}" placeholder="${esc(t('Kullanıcı adı, isim, not ara','Search username, name, notes'))}"><select id="category" aria-label="Filter">${['all','nonfollowers','mutual','protected','favorites','selected','review','reviewed','new'].map(v=>`<option value="${v}" ${category===v?'selected':''}>${esc(({all:t('Tümü','All'),nonfollowers:t('Geri takip etmeyen','Non-followers'),mutual:t('Karşılıklı','Mutual'),protected:t('Korumalı','Protected'),favorites:t('Favoriler','Favorites'),selected:t('Seçili','Selected'),review:t('İnceleme','Review'),reviewed:t('İncelendi','Reviewed'),new:t('Yeni gözlem','New observation')})[v])}</option>`).join('')}</select><select id="sort" aria-label="Sort">${['username-asc','username-desc','name-asc','relationship','protected','selected','firstObserved','lastObserved'].map(v=>`<option value="${v}" ${v===sort?'selected':''}>${esc(({ 'username-asc':t('Kullanıcı adı A–Z','Username A–Z'),'username-desc':t('Kullanıcı adı Z–A','Username Z–A'),'name-asc':t('Görünen isim','Display name'),relationship:t('İlişki','Relationship'),protected:t('Koruma','Protection'),selected:t('Seçim','Selection'),firstObserved:t('İlk saklı gözlem','First retained observation'),lastObserved:t('Son saklı gözlem','Last retained observation')})[v]||v)}</option>`).join('')}</select>${btn('search-clear',t('Aramayı temizle','Clear search'))}${btn('filter',t('Birleşik koşullar','Combined conditions'))}</div><div class="toolbar">${btn('select-visible',t('Görünenleri seç','Select displayed'))}${btn('select-all',t('Tüm eşleşmeleri seç','Select all matches'))}${btn('invert',t('Görünen seçimi tersle','Invert displayed'))}${btn('clear',t('Temizle','Clear'))}${btn('save-selection',t('Seçimi kaydet','Save selection'))}${btn('restore-selection',t('Seçimi yükle','Restore selection'))}${btn('queue',t('İncelemeye ekle','Add to review'))}${btn('export',t('Dışa aktar','Export'),'','primary')}${btn('export-protection',t('Koruma listesi indir','Export protection'))}${btn('import-protection',t('Koruma listesi yükle','Import protection'))}</div><p><span id="selection-status">${selected.size}</span> ${t('seçili (filtre dışındakiler dahil). Korumalı hesaplar seçilmez.','selected (including hidden selections). Protected accounts are excluded.')}</p>${table(matches())}`}
function reviews(){const list=rows().filter(u=>acc().reviews.includes(u.id));if(!list.length)return `<div class="empty">${t('İnceleme sırası boş. Hesaplar ekranından ekle.','Review queue is empty. Add accounts from Accounts.')}</div>`;position=Math.min(position,list.length-1);const u=list[position];return `<section class="section"><h2>@${esc(u.username)}</h2><p>${position+1}/${list.length} · ${esc(u.full_name)}</p><p>${esc(u.notes)}</p><a href="https://www.instagram.com/${encodeURIComponent(u.username)}/" target="_blank" rel="noopener noreferrer">${t('Profili aç','Open profile')}</a><div class="toolbar">${btn('previous',t('Önceki','Previous'))}${btn('next',t('Atla / sonraki','Skip / next'))}${btn('reviewed',t('İncelendi','Reviewed'),u.id,'primary')}${btn('protect',u.protected?t('Korumayı kaldır','Unprotect'):t('Koru','Protect'),u.id)}${btn('note',t('Not / etiket','Note / labels'),u.id)}${btn('remove-review',t('Sıradan çıkar','Remove from queue'),u.id)}</div></section>`}
function sessions(){return `<div class="toolbar">${btn('new-session',t('Yeni oturum','New session'),'','primary')}${btn('archives',showArchived?t('Arşivi gizle','Hide archived'):t('Arşivi göster','Show archived'))}</div><section class="section">${acc().sessions.filter(s=>!s.archived||showArchived).map(s=>`<div class="row"><div><strong>${esc(s.name)}</strong><small> · ${s.position}/${s.ids.length} · ${esc(date(s.at))}</small></div><div>${btn('resume-session',t('Devam et','Resume'),s.id)}${btn('archive-session',t('Arşivle','Archive'),s.id)}</div></div>`).join('')||'—'}</section>`}
function tasks(){return `<div class="toolbar">${btn('new-task',t('Yeni görev','New task'),'','primary')}${btn('archives',showArchived?t('Arşivi gizle','Hide archived'):t('Arşivi göster','Show archived'))}</div><section class="section">${acc().tasks.filter(s=>!s.archived||showArchived).sort((a,b)=>Number(a.done)-Number(b.done)||String(a.due||'9999').localeCompare(b.due||'9999')).map(s=>`<div class="row"><div><strong>${s.done?'✓ ':''}${esc(s.title)}</strong><small> · ${esc(s.priority)} · ${esc(date(s.due))}</small></div><div>${btn('task-done',t('Tamamla / aç','Complete / reopen'),s.id)}${btn('task-postpone',t('Yarına ertele','Postpone one day'),s.id)}${btn('task-archive',t('Arşivle','Archive'),s.id)}</div></div>`).join('')||'—'}</section>`}
function workflowCanvas(w){
 const places=new Map(w.nodes.map((n,i)=>[n.id,{x:Math.max(10,Math.min(7000,Number.isFinite(n.x)?n.x:20+i*175)),y:Math.max(15,Math.min(1500,Number.isFinite(n.y)?n.y:25))}]));
 const width=Math.max(700,...[...places.values()].map(p=>p.x+165)),height=Math.max(180,...[...places.values()].map(p=>p.y+235));
 const edges=w.edges.map(e=>{const from=places.get(e.from),to=places.get(e.to);if(!from||!to)return '';return `<path d="M ${from.x+135} ${from.y+35} C ${from.x+160} ${from.y+35},${to.x-30} ${to.y+35},${to.x} ${to.y+35}" fill="none" stroke="currentColor" stroke-width="2" marker-end="url(#workspace-arrow)"/>`}).join('');
 const names={start:t('Başlat','Start'),load:t('Veriyi yükle','Load scan'),condition:t('Koşul','Condition'),sort:t('Sırala','Sort'),review:t('İnceleme','Review'),approval:t('Onay','Approval'),notify:t('Bildirim','Notification'),report:t('Rapor','Report'),end:t('Bitir','End')};
 return `<div class="workflow-canvas" style="position:relative;width:${width}px;height:${height}px"><svg width="${width}" height="${height}" style="position:absolute;inset:0;color:var(--accent)" aria-hidden="true"><defs><marker id="workspace-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor"/></marker></defs>${edges}</svg>${w.nodes.map(n=>`<div class="node" draggable="true" data-node="${esc(n.id)}" style="position:absolute;left:${places.get(n.id).x}px;top:${places.get(n.id).y}px;width:135px"><strong>${esc(names[n.type])}</strong><small>${esc(n.id)}</small>${n.type==='condition'?btn('edit-rule',t('Koşul','Condition'),n.id):''}<div class="ports">${n.type!=='start'?btn('connect-to',t('← Giriş','← Input'),n.id):''}${n.type!=='end'?btn('connect-from',connectionFrom===n.id?t('Çıkış seçili','Output selected'):t('Çıkış →','Output →'),n.id):''}</div>${!['start','end'].includes(n.type)?btn('remove-node',t('Adımı sil','Remove step'),n.id):''}</div>`).join('')}</div>`;
}
function workflows(){editing??=W.copy(acc().workflows[0]||W.template(t('İlişki incelemesi','Relationship review')));return `<div class="toolbar"><select id="workflow-choice" aria-label="Workflow">${[editing,...acc().workflows.filter(w=>w.id!==editing.id)].map(w=>`<option value="${esc(w.id)}">${esc(w.name)}</option>`).join('')}</select>${btn('new-workflow',t('Şablon','Template'))}${btn('save-workflow',t('Kaydet','Save'))}${btn('duplicate-workflow',t('Çoğalt','Duplicate'))}${btn('delete-workflow',t('Sil','Delete'))}${btn('import-workflow',t('İçe aktar','Import'))}${btn('export-workflow',t('Dışa aktar','Export'))}</div><section class="section"><label>${t('İş akışı adı','Workflow name')}<input id="workflow-name" maxlength="80" value="${esc(editing.name)}"></label><p class="muted">${t('Kartları sürükle. Bağlantı için önce Çıkış, ardından hedef kartta Giriş seç. Silinen bağlantıları aşağıdan yeniden kurabilirsin.','Drag cards to move them. Choose an Output then an Input to connect. Remove connections below.')}</p><div class="workflow-nodes">${workflowCanvas(editing)}</div><div class="edge-list">${editing.edges.map((e,i)=>`<div class="row"><span>${esc(e.from)} → ${esc(e.to)}</span>${btn("remove-edge",t("Bağlantıyı sil","Remove connection"),String(i))}</div>`).join('')}</div><div class="toolbar"><select id="node-type" aria-label="Node"><option>condition</option><option>sort</option><option>review</option><option>approval</option><option>notify</option><option>report</option></select>${btn('add-node',t('Adım ekle','Add step'))}${btn('workflow-json',t('JSON / bağlantılar','JSON / connections'))}${btn('simulate',t('Yalnızca simülasyon','Simulation only'),'','primary')}${editing.nodes.some(n=>n.reportKind)?btn('run-template',t('İlgili aracı aç','Open relevant tool')):''}</div></section>${simulation?`<section class="section"><h2>${t('Simülasyon','Simulation')}</h2><p>${simulation.matching.length} ${t('eşleşen','matched')} · ${simulation.excluded.length} ${t('dışarıda','excluded')} · ${simulation.missing.length} ${t('eksik veri','missing data')} · <strong>0 ${t('Instagram isteği','Instagram requests')}</strong></p>${btn('apply-simulation',t('Yerel adımları uygula','Apply local steps'),'','primary')}${btn('export-simulation',t('Simülasyon raporunu indir','Download simulation report'))}<pre>${esc(JSON.stringify(simulation.steps,null,2))}</pre>${table(simulation.matching)}</section>`:''}<section class="section"><h2>${t('Simülasyon geçmişi','Simulation history')}</h2>${acc().runs.slice(-10).reverse().map(r=>`<p>${esc(r.name)} · ${r.matched} · ${esc(date(r.at))}</p>`).join('')||'—'}</section>`}
function snapshots(){return `<section class="section"><h2>${t('Yerel tarama geçmişi','Local scan history')}</h2>${chartControls()}${chart()}${acc().snapshots.map(s=>`<div class="row"><div>${esc(date(s.at))} · ${s.users.length} / ${s.followerIds?.length??'—'} · ${esc(s.scope)}</div>${btn('delete-snapshot',t('Sil','Delete'),s.id)}</div>`).join('')}</section><section class="section"><h2>${t('Karşılaştırma','Comparison')}</h2><div class="toolbar"><select id="compare-a" aria-label="Earlier scan">${acc().snapshots.map(s=>`<option value="${s.id}">${esc(date(s.at))}</option>`).join('')}</select><select id="compare-b" aria-label="Later scan">${acc().snapshots.map((s,i)=>`<option value="${s.id}" ${i===acc().snapshots.length-1?'selected':''}>${esc(date(s.at))}</option>`).join('')}</select>${btn('compare',t('Karşılaştır','Compare'))}</div><p class="muted">${t('Yeni taramada görünmemek isteyerek takip bırakıldığını kanıtlamaz; silinme, kapanma, engelleme veya veri kısıtları da etkileyebilir.','Absence does not prove intentional unfollowing; deletion, deactivation, blocking or data limits can affect lists.')}</p><pre id="comparison"></pre></section>`}
function operationHistory(){return `<section class="section"><h2>${t('İşlem geçmişi','Operation history')}</h2><div class="toolbar"><input type="search" id="history-search" placeholder="${esc(t('Kullanıcı veya kod ara','Search user or code'))}">${btn('export-history',t('Dışa aktar','Export'))}</div>${history.filter(e=>e.accountId===viewer).slice().reverse().map(e=>`<div class="row" data-history="${esc((e.username+' '+e.code).toLowerCase())}"><div><strong>@${esc(e.username||e.targetId)}</strong><small> · ${esc(e.category||'unknown')} · ${esc(e.code)} · ${esc(date(e.at))}</small></div>${tag(e.operationId||'—')}</div>`).join('')||'—'}</section>`}
async function health(){const bytes=await chrome.storage.local.getBytesInUse(null),m=chrome.runtime.getManifest(),data=await chrome.storage.local.get('iu_all_following_scan_v1');const log=(await chrome.storage.session.get('iu_live_log_v1')).iu_live_log_v1||[];let messaging=false;try{messaging=(await chrome.runtime.sendMessage({type:'IU_HEALTH_PING'}))?.ok===true}catch{}let browser='Chromium / Chrome';try{if(await navigator.brave?.isBrave())browser='Brave'}catch{}return `<div class="grid">${[[t('Sürüm','Version'),m.version],['Manifest','V'+m.manifest_version],[t('Tarayıcı','Browser'),browser],[t('Depolama','Storage'),(bytes/1024).toFixed(1)+' KB'],[t('Belirsiz kayıt','Uncertain records'),history.filter(e=>e.accountId===viewer&&e.category==='uncertain').length],[t('Yarım tarama','Incomplete scan'),data.iu_all_following_scan_v1?t('Var','Present'):t('Yok','None')],[t('Bekleyen görevler','Pending tasks'),acc().tasks.filter(v=>!v.done&&!v.archived).length],[t('Eklenti mesajlaşması','Extension messaging'),messaging?t('Bağlı','Connected'):t('Yanıt yok','No response')]].map(([n,v])=>`<div class="card"><small>${esc(n)}</small><strong>${esc(v)}</strong></div>`).join('')}</div><section class="section"><h2>${t('Gözlenen sağlık bilgisi','Observed health information')}</h2><p>${t('Depolama erişimi kontrol edildi. Bu bilgi Instagram API entegrasyonunun çalıştığını kanıtlamaz. Asistana otomatik aktarım yok.','Storage access was checked. This does not prove Instagram API compatibility. There is no automatic assistant connection.')}</p>${bytes>(chrome.storage.local.QUOTA_BYTES||5242880)*.85?`<p class="error">${t('Depolama sınırına yaklaşıldı. Eski taramaları yedekleyip temizleyebilirsin.','Storage is close to its limit. Back up and remove older scans.')}</p>`:''}<div class="toolbar">${btn('diagnostic',t('Tanı sihirbazı','Diagnostic wizard'))}${btn('support',t('Destek paketi','Support package'))}<a href="logs.html">${t('Canlı günlük','Live log')}</a></div><pre>${esc(JSON.stringify(log.slice(-8).map(e=>({event:e.event,status:e.status,reason:e.reason})),null,2))}</pre></section>`}
function faqs(){return [[t('Eklenti açılmıyor','Extension does not open'),t('Instagram’a giriş yapıp eklenti simgesine tıkla. Eklentiyi yeniden yükledikten sonra Instagram sekmesini yenile.','Sign into Instagram and click the extension icon. Refresh Instagram after reloading the extension.')],[t('HTML / boş yanıt','HTML / empty response'),t('HTTP 200 başarı kanıtı değildir. Belirsiz işlem durur; gizli veri içermeyen tanı kaydını indir.','HTTP 200 is not proof of success. Uncertain operations stop; export sanitized diagnostics.')],[t('Eksik veri ve bilinmeyen oran','Incomplete data and unknown ratios'),t('Takipçi verisi yoksa karşılıklı takip ve oranlar bilinmiyor gösterilir. Yarım tarama kullanılamaz.','Missing follower data produces unknown relationship counts and ratios. Incomplete scans cannot be used.')],[t('Yerel veriler','Local data'),t('Notlar, görevler, koruma ve taramalar cihazda saklanır. Ayarlar’dan yedekleyebilir veya silebilirsin.','Notes, tasks, protection and scans remain on device. Back up or delete them in Settings.')],[t('Kısayollar','Shortcuts'),shortcutReference()],[t('Belirsiz işlem','Uncertain operation'),t('Sunucu işlemi yapmış olabilir; yeterli doğrulama yoktur. Otomatik yeniden gönderilmez. Instagram’da manuel kontrol et.','The server may have acted, but verification is insufficient. Never automatically replayed; review manually on Instagram.')]]}
function help(){return `<section class="section"><div class="toolbar"><input type="search" id="help-search" placeholder="${esc(t('Yardımda ara','Search help'))}">${btn('onboarding',t('Başlangıç rehberi','Onboarding'))}${btn('update-details',t('Sürüm notları','Release notes'))}</div>${faqs().map(([q,v])=>`<article class="faq"><h3>${esc(q)}</h3><p>${esc(v)}</p></article>`).join('')}<a href="privacy.html">${t('Gizlilik','Privacy')}</a></section>`}
function settings(){const p=acc().preferences;return `<section class="section"><h2>${t('Yerel tercihler','Local preferences')}</h2><div class="stack"><label>${t('Tema','Theme')}<select id="pref-theme"><option value="dark" ${p.theme==='dark'?'selected':''}>${t('Koyu','Dark')}</option><option value="light" ${p.theme==='light'?'selected':''}>${t('Açık','Light')}</option></select></label><label class="inline"><input type="checkbox" id="pref-compact" ${p.compact?'checked':''}>${t('Kompakt görünüm','Compact layout')}</label><label>${t('Saklanacak tarama sayısı (1–20)','Snapshot retention (1–20)')}<input id="pref-retention" type="number" min="1" max="20" value="${p.retention||5}"></label><label>${t('Palet kısayolu','Palette shortcut')}<select id="pref-shortcut"><option value="k" ${p.shortcut!=='j'?'selected':''}>Ctrl / ⌘ + K</option><option value="j" ${p.shortcut==='j'?'selected':''}>Ctrl / ⌘ + J</option></select></label><label class="inline"><input type="checkbox" id="pref-reminders" ${p.notifications?'checked':''}>${t('Bu sayfa açıkken yerel görev hatırlatmaları','Local due-task reminders while this page is open')}</label><label class="inline"><input type="checkbox" id="pref-lab" ${p.flags?.advanced?'checked':''}>${t('Deneysel laboratuvar: ek yerel öneriler','Experimental lab: additional local suggestions')}</label><label>${t('Varsayılan sıralama','Default sort')}<select id="pref-sort">${['username-asc','username-desc','name-asc','relationship','protected','selected','firstObserved','lastObserved'].map(v=>`<option value="${v}" ${p.defaultSort===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>${t('Varsayılan filtre','Default filter')}<select id="pref-filter">${['all','nonfollowers','mutual','protected','favorites','selected','review','reviewed','new'].map(v=>`<option value="${v}" ${p.defaultFilter===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>${t('Varsayılan dışa aktarma','Default export')}<select id="pref-export">${['JSON','CSV','TXT'].map(v=>`<option ${p.exportFormat===v?'selected':''}>${v}</option>`).join('')}</select></label><fieldset><legend>${t('Gösterilecek kartlar','Visible cards')}</legend>${[t('Takip edilen','Following'),t('Takipçi','Followers'),t('Geri takip etmeyen','Non-followers'),t('Karşılıklı','Mutual'),t('Korumalı','Protected'),t('Seçili','Selected')].map((v,i)=>`<label class="inline"><input type="checkbox" data-card="${i}" ${!(p.hiddenCards||[]).includes(i)?'checked':''}>${esc(v)}</label>`).join('')}</fieldset><label class="inline"><input id="pref-shortcuts" type="checkbox" ${p.shortcuts!==false?'checked':''}>${t('Ek klavye kısayollarını aç','Enable additional shortcuts')}</label><p class="muted">${shortcutReference()}</p>${btn('save-settings',t('Kaydet','Save'),'','primary')}${btn('reset-settings',t('Varsayılanlar','Restore defaults'))}</div></section><section class="section"><h2>${t('Veri yönetimi','Data management')}</h2><div class="toolbar">${btn('backup',t('Yedek indir','Download backup'))}${btn('import-backup',t('Yedek önizle / yükle','Preview / import backup'))}${btn('delete-history',t('Kesinleşmiş geçmişi sil','Delete settled history'))}${btn('export-quarantine',t('Kurtarma karantinasını indir','Download recovery quarantine'))}${btn('delete-quarantine',t('Kurtarma karantinasını sil','Delete recovery quarantine'))}${btn('delete-data',t('Bu hesabın yerel verisini temizle','Clear account workspace'))}</div></section>`}
let reminded=false;
async function render(){
 document.documentElement.lang=lang;$('undo').textContent=t('↶ Geri al','↶ Undo');$('undo').disabled=!undoState||undoState.accountId!==viewer;$('error').hidden=true;$('nav').innerHTML=Object.keys(titles).map(k=>btn('nav',title(k),k,k===page?'active':'')).join('');$('title').textContent=title(page).slice(2);$('eyebrow').textContent=t('YEREL VERİ · KULLANICI KONTROLÜ','LOCAL DATA · USER CONTROL');$('lang').textContent=lang==='tr'?'EN':'TR';$('help-link').textContent=t('Yardım','Help');$('account').innerHTML=Object.keys(db.accounts).map(k=>`<option value="${k}" ${k===viewer?'selected':''}>${esc(t('Hesap ','Account ')+k)}</option>`).join('')||'<option>—</option>';$('offline').textContent=t('Kayıtlı veriler güncel Instagram ilişkilerini garanti etmez. Görevler, kurallar ve simülasyonlar Instagram’a işlem göndermez.','Stored data does not guarantee current Instagram relationships. Tasks, rules and simulations send no Instagram mutations.');$('footer').textContent='Takip Paneli · '+chrome.runtime.getManifest().version+' · '+t('Instagram / Meta ile bağlantılı değildir.','Not affiliated with Instagram / Meta.');
 if(!viewer){$('view').innerHTML=`<section class="section empty"><h2>${t('İlk taramanı kaydet','Save your first scan')}</h2><p>${t('Instagram’da eklentiyi açıp tam bir tarama yap. Veriler burada yerel olarak görünür.','Open the extension on Instagram and complete a scan. Results will appear here locally.')}</p><a href="https://www.instagram.com/" target="_blank" rel="noopener noreferrer">Instagram</a></section>`;return}
 document.body.classList.toggle('light',acc().preferences.theme==='light');document.body.classList.toggle('compact',!!acc().preferences.compact);
 const expected=page,output=await ({overview,accounts,review:reviews,sessions,tasks,workflows,snapshots,history:operationHistory,health,help,settings})[page]();if(page===expected)$('view').innerHTML=output;if(!reminded&&acc().preferences.notifications&&acc().tasks.some(v=>!v.done&&!v.archived&&v.due&&new Date(v.due)<new Date())){reminded=true;toast(t('İnceleme zamanı gelmiş yerel görevlerin var.','Some local review tasks are due.'))}
}
