 'search-clear':()=>{clearTimeout(searchTimer);query='';offset=0;render().then(()=>$('search')?.focus())},nav:el=>{offset=0;return go(el.dataset.id)},'table-prev':()=>{offset=Math.max(0,offset-200);render()},'table-next':()=>{offset=Math.min(Math.max(0,(Math.ceil(matches().length/200)-1)*200),offset+200);render()},'select-visible':()=>{matches().slice(offset,offset+200).filter(u=>!u.protected).forEach(u=>selected.add(u.id));render()},'select-all':()=>{matches().filter(u=>!u.protected).forEach(u=>selected.add(u.id));render()},clear:()=>{selected.clear();render()},invert:()=>{matches().slice(offset,offset+200).filter(u=>!u.protected).forEach(u=>{if(selected.has(u.id))selected.delete(u.id);else selected.add(u.id)});render()},
