let commandIndex=0;
function fuzzy(query,value){let at=0;for(const c of value.toLowerCase())if(c===query[at])at++;return at===query.length;}

function renderCommands(){const q=$('command-search').value.toLowerCase(),keys=Object.keys(titles).filter(k=>fuzzy(q,title(k)));commandIndex=Math.min(commandIndex,Math.max(0,keys.length-1));$('commands').innerHTML=keys.map((k,i)=>`<button role="option" aria-selected="${i===commandIndex}" data-command="${k}">${esc(title(k))}</button>`).join('');return keys}
