$('palette-open').onclick=palette;$('command-search').oninput=()=>{commandIndex=0;renderCommands()};$('commands').onclick=event=>{const el=event.target.closest('[data-command]');if(el){$('palette').close();go(el.dataset.command)}};
$('command-search').onkeydown=event=>{if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();commandIndex=Math.max(0,commandIndex+(event.key==='ArrowDown'?1:-1));renderCommands()}if(event.key==='Enter'){event.preventDefault();const keys=renderCommands();if(keys[commandIndex]){$('palette').close();go(keys[commandIndex])}}};
document.addEventListener('keydown',event=>{if(!event.ctrlKey&&!event.metaKey&&!event.altKey&&!event.target.closest('input,textarea,select,[contenteditable=true]')&&!$('dialog').open&&!$('palette').open&&viewer&&acc().preferences.shortcuts!==false){const key=event.key.toLowerCase();const map={'/':async()=>{await go('accounts');$('search')?.focus()},'s':()=>page==='accounts'&&actions['select-visible'](),'x':()=>actions.clear(),'r':()=>go('review'),'arrowright':()=>page==='review'&&actions.next(),'arrowleft':()=>page==='review'&&actions.previous(),'p':()=>{const list=page==='review'?rows().filter(u=>acc().reviews.includes(u.id)).slice(position,position+1):chosen();if(list.length)return dialog(t('Seçimi koru?','Protect selection?'),`<p>${list.length} ${t('hesap. Yalnızca yerel koruma uygulanır.','accounts. Local protection only.')}</p>`,()=>save(x=>{for(const u of list){x.meta[u.id]={...x.meta[u.id],protected:true};selected.delete(u.id)}}))}};if(map[key]){event.preventDefault();Promise.resolve(map[key]()).catch(fail);return;}}const key=viewer?acc().preferences.shortcut||'k':'k';if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()===key){event.preventDefault();if(!$('dialog').open&&!$('palette').open)palette()}});
