function ruleEditor(value,onSave,canClear=false){
 const flat=['and','or'].includes(value.op)&&value.rules.every(v=>!['and','or','not'].includes(v.op)),simple=!['and','or','not'].includes(value.op),mode=flat||simple?'basic':'json';
 dialog(t('Koşullar','Conditions'),`<label>${t('Düzenleme biçimi','Editing mode')}<select id="rule-mode"><option value="basic" ${mode==='basic'?'selected':''}>${t('Form','Form')}</option><option value="json" ${mode==='json'?'selected':''}>${t('Gelişmiş JSON / iç içe gruplar','Advanced JSON / nested groups')}</option></select></label><label>${t('Grup','Group')}<select id="rule-group"><option value="and">${t('Hepsi (AND)','All (AND)')}</option><option value="or" ${value.op==='or'?'selected':''}>${t('Herhangi biri (OR)','Any (OR)')}</option></select></label><div id="rule-rows">${(flat?value.rules:simple?[value]:[]).map(ruleRow).join('')}</div>${btn('rule-add',t('Koşul ekle','Add condition'))}<p>${t('Mantıksal alanlar için true / false yaz. Bilinmeyen değer eşleşmez. JSON, NOT ve iç içe grupları destekler.','Use true / false for boolean fields. Unknown values do not match. JSON supports NOT and nested groups.')}</p><textarea id="rule-json">${esc(JSON.stringify(value,null,2))}</textarea>${canClear?`<label class="inline"><input type="checkbox" id="rule-clear">${t('Filtreyi temizle','Clear filter')}</label>`:''}`,()=>{if(canClear&&$('rule-clear').checked){onSave(null);return}let r;if($('rule-mode').value==='json')r=JSON.parse($('rule-json').value);else{const rules=[...document.querySelectorAll('.rule-row')].map(row=>{const text=row.querySelector('[data-rule-value]').value;return {field:row.querySelector('[data-rule-field]').value,op:row.querySelector('[data-rule-op]').value,value:text==='true'?true:text==='false'?false:text}});r={op:$('rule-group').value,rules}}W.validateRule(r);if(W.ruleConflicts(r).length)throw Error(t('Çelişen koşullar: aynı alan farklı değerler istiyor.','Conflicting rules require different values for the same field.'));onSave(r)})
}
